test("deck, patioSet, frenchDoor", () => {
  V.deck(g, 14, 24, 32, 30, { rail: ["east", "west", "south"], skip: (x, z) => z === 30 && x >= 22 && x <= 24 });
  expect("boards", 20, 1, 26, "spruce_planks");
